package com.luminor.tavernquest.data.local.database.dao
import androidx.room.*; import com.luminor.tavernquest.data.local.database.entity.DailyContractEntity; import com.luminor.tavernquest.data.local.database.relation.DailyContractWithTemplate; import kotlinx.coroutines.flow.Flow
@Dao interface DailyContractDao{@Query("UPDATE daily_contract SET startedAt=:now WHERE id=:id AND startedAt IS NULL AND status='ACCEPTED'") suspend fun start(id:String,now:Long):Int;@Insert(onConflict=OnConflictStrategy.IGNORE) suspend fun insertAll(v:List<DailyContractEntity>);@Transaction @Query("SELECT * FROM daily_contract WHERE heroId=:heroId AND (date=:date OR (status='ACCEPTED' AND startedAt IS NOT NULL)) ORDER BY id") suspend fun getByDate(date:String,heroId:String):List<DailyContractWithTemplate>;@Transaction @Query("SELECT * FROM daily_contract WHERE id=:id LIMIT 1") suspend fun getById(id:String):DailyContractWithTemplate?;@Transaction @Query("SELECT * FROM daily_contract WHERE heroId=:heroId AND (date=:date OR (status='ACCEPTED' AND startedAt IS NOT NULL)) ORDER BY id") fun observeByDate(date:String,heroId:String):Flow<List<DailyContractWithTemplate>>;@Query("SELECT COUNT(*) FROM daily_contract WHERE heroId=:heroId AND date=:date AND status IN ('ACCEPTED','COMPLETED')") suspend fun countAcceptedByDate(date:String,heroId:String):Int;@Query("UPDATE daily_contract SET status=:status, acceptedAt=:acceptedAt, completedAt=:completedAt WHERE id=:id") suspend fun updateStatus(id:String,status:String,acceptedAt:Long?,completedAt:Long?);@Query("UPDATE daily_contract SET status='EXPIRED' WHERE date<:date AND (status='AVAILABLE' OR (status='ACCEPTED' AND startedAt IS NULL))") suspend fun expireBefore(date:String);@Query("DELETE FROM daily_contract") suspend fun deleteAll()}
